/// <summary>
/// SysOperation controller for the Purchase Requisition Line Processing Status Reset
/// periodic-cleanup operation.
///
/// Navigation:  Procurement and sourcing > Periodic tasks > Clean up
/// </summary>
class PurchReqLineProcessingStatusResetController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Initialises the controller, wiring it to the service method.
/// </summary>
public void new()
{
    super(classStr(PurchReqLineProcessingStatusResetService),
          methodStr(PurchReqLineProcessingStatusResetService, resetProcessingStatus),
          SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Entry point invoked by the action menu item.
/// </summary>
/// <param name="_args">Standard Args object (not used).</param>
public static void main(Args _args)
{
    PurchReqLineProcessingStatusResetController controller =
        new PurchReqLineProcessingStatusResetController();

    controller.parmDialogCaption('Reset purchase requisition processing status');
    controller.startOperation();
}

/// <summary>
/// Returns the default dialog caption shown in the batch task list.
/// </summary>
public ClassDescription defaultCaption()
{
    return 'Reset purchase requisition processing status';
}
